325	// AddRequirement 为学生登记一项指向课程的要求。
326	// 同一要求编号已存在且指向同一课程时返回原要求（幂等）；指向不同课程则拒绝。
327	// 同一学生就同一课程已有要求（即使编号不同）也拒绝。学生或课程不存在时拒绝。
328	func (s *Store) AddRequirement(studentID, reqID, courseID string) (r *Requirement, action Action, err error) {
329		studentID = strings.TrimSpace(studentID)
330		reqID = strings.TrimSpace(reqID)
331		courseID = strings.TrimSpace(courseID)
332		if studentID == "" || reqID == "" {
333			return nil, "", errors.New("学生编号和要求编号不能为空")
334		}
335		if _, ok := s.studentByID[studentID]; !ok {
336			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记课程要求", studentID)
337		}
338		c := s.courseByID[courseID]
339		if c == nil {
340			return nil, "", fmt.Errorf("课程 %s 不存在，不能登记课程要求", courseID)
341		}
342		if existing := s.reqByKey[reqKey(studentID, reqID)]; existing != nil {
343			if existing.CourseID != courseID {
344				return nil, "", fmt.Errorf(
345					"学生 %s 的要求编号 %s 已指向课程 %s，不能改指课程 %s",
346					studentID, reqID, existing.CourseID, courseID)
347			}
348			return existing, ActionExisted, nil
349		}
350		if otherID, ok := s.reqByDup[dupKey(studentID, courseID)]; ok {
351			return nil, "", fmt.Errorf(
352				"学生 %s 已就课程 %s 建立要求 %s，不能重复建立", studentID, courseID, otherID)
353		}
354		r = &Requirement{ID: reqID, StudentID: studentID, CourseID: courseID}
355		s.requirements = append(s.requirements, r)
356		s.reqByKey[reqKey(studentID, reqID)] = r
357		s.reqByDup[dupKey(studentID, courseID)] = reqID
358		s.dirty = true
359		return r, ActionCreated, nil
360	}
