362	// ---------- 修读 ----------
363	
364	// AddEnrollment 为学生的一项要求登记某学期的修读，初始状态为“选课”。
365	// 相同（学生、修读编号、要求、学期）的重复登记返回原记录（幂等）；
366	// 相同编号但要求或学期不同则拒绝；课程已停开时不能新增修读
367	// （已登记记录的重复提交仍按幂等返回原记录）。
368	//
369	// 学生编号、要求编号与修读编号按用户给出的完整文字参与匹配，前后空白
370	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
371	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
372	// 要求、“e1” 与 “ e1 ” 两份修读，登记必须命中编号完全一致的对象，新
373	// 修读也必须登记在完整编号的学生与要求名下并保留完整编号。完整编号找
374	// 不到学生时报告学生不存在；学生存在但名下没有该完整要求编号时报告本人
375	// 名下没有该要求——即使去掉空白能碰上另一名学生或另一项要求，也绝不
376	// 借用那份记录，更不能把修读登记到别人名下。编号为空字符串时直接拒绝；
377	// 只由空白字符组成的修读编号不得建立。学期沿用现有输入规则：前后空白
378	// 不计入学期内容，修剪后为空则拒绝。
379	func (s *Store) AddEnrollment(studentID, reqID, term, enrID string) (e *Enrollment, action Action, err error) {
380		term = strings.TrimSpace(term)
381		if studentID == "" || reqID == "" || enrID == "" {
382			return nil, "", errors.New("学生编号、要求编号和修读编号不能为空")
383		}
384		if strings.TrimSpace(enrID) == "" {
385			return nil, "", errors.New("修读编号不能只由空白字符组成")
386		}
387		if term == "" {
388			return nil, "", errors.New("学期不能为空")
389		}
390		if _, ok := s.studentByID[studentID]; !ok {
391			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记修读", studentID)
392		}
393		r := s.reqByKey[reqKey(studentID, reqID)]
394		if r == nil {
395			return nil, "", fmt.Errorf("学生 %s 名下不存在要求 %s，不能登记修读", studentID, reqID)
396		}
397		if existing := s.enrByKey[reqKey(studentID, enrID)]; existing != nil {
398			if existing.ReqID != reqID || existing.Term != term {
399				return nil, "", fmt.Errorf(
400					"学生 %s 的修读编号 %s 已用于要求 %s、学期 %s，不能改为要求 %s、学期 %s",
401					studentID, enrID, existing.ReqID, existing.Term, reqID, term)
402			}
403			return existing, ActionExisted, nil
404		}
405		c := s.courseByID[r.CourseID]
406		if c == nil || !c.Open {
407			return nil, "", fmt.Errorf("课程 %s 已停开，不能新增修读", r.CourseID)
408		}
409		e = &Enrollment{
410			ID: enrID, StudentID: studentID, ReqID: reqID, Term: term, Result: Enrolled,
411		}
412		s.enrollments = append(s.enrollments, e)
413		s.enrByKey[reqKey(studentID, enrID)] = e
414		s.dirty = true
415		return e, ActionCreated, nil
416	}
417	
418	// SubmitResult 为修读提交通过/未通过结果。
419	// 重复提交相同结果返回原记录（幂等，不累加学分）；已提交结果后改提另一结果
420	// 一律拒绝并保留原记录。
421	//
422	// 首次提交结果会从全局递增计数器领取一个结果提交序号（ResultSeq），用于
423	// 记录多次提交的先后关系；通过与未通过都占用一次序号。计数器是整数类型
424	// int：当它已经达到该类型可表示的最大值（64 位环境下为
425	// 9223372036854775807）时，再递增必然回绕成负数并保存，会破坏整份记录
426	// （负序号、与原有序号的先后关系错乱、记录无法再正常读取）。因此计数已
427	// 到上限时，任何仍处于“选课”的修读都不能再首次提交结果：明确拒绝，不
428	// 改结果、不发序号、不标记变更；不会因该要求已有另一份通过修读或已有
429	// 有效免修而放行，也不能从小重新编号、借用历史空缺编号或改排已有成绩。
430	// 距上限恰好还差一时允许最后一次正常的首次提交，其先后关系照常保留；
431	// 未通过同样占用这最后一次机会且仍不计学分。已经提交过结果的修读不
432	// 需要新序号：重复提交相同结果仍幂等返回原记录，改提另一结果仍按冲突
433	// 规则拒绝。
434	//
435	// 学生编号与修读编号按用户给出的完整文字参与匹配，前后空白（普通空格、
436	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
437	// “s1”与“ s1 ”两名学生、同一学生名下“e1”与“ e1 ”两份修读，提交
438	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
439	// 学生存在但名下没有该完整修读编号时报告该修读不存在——即使去掉空白后
440	// 能碰上另一名学生或另一份修读，也绝不借用那份记录，更不能据此补建修读。
441	func (s *Store) SubmitResult(studentID, enrID string, result Result) (e *Enrollment, changed bool, err error) {
442		if result != Passed && result != Failed {
443			return nil, false, fmt.Errorf("修读结果只能是 %s 或 %s", Passed, Failed)
444		}
445		if _, ok := s.studentByID[studentID]; !ok {
446			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
447		}
448		e = s.enrByKey[reqKey(studentID, enrID)]
449		if e == nil {
450			return nil, false, fmt.Errorf("学生 %s 名下不存在修读 %s", studentID, enrID)
451		}
452		if e.Result == result {
453			return e, false, nil
454		}
455		if e.Result != Enrolled {
456			return nil, false, fmt.Errorf(
457				"修读 %s 已提交结果“%s”，不能改为“%s”，原结果保留", enrID, zhResult(e.Result), zhResult(result))
458		}
459		// 首次提交必须领取新的结果序号。计数器已达 int 上限时不能再递增：
460		// MaxInt+1 会静默回绕成 MinInt 并随修读落盘，随后连原有记录都无法
461		// 正常读取。这里在改动任何状态之前拒绝，保持修读为选课、整份记录
462		// 原样不变。是否还能提交只取决于计数器本身：不重新从小编号、不
463		// 借用历史空缺编号，也不因该要求另有通过修读或有效免修而放行。
464		if s.nextResultSeq >= math.MaxInt {
465			return nil, false, fmt.Errorf(
466				"学生 %s 的修读 %s 不能提交成绩：成绩提交顺序编号已用尽（已达本程序整数类型最大值 %d），无法提交新的成绩，原记录保留",
467				studentID, enrID, math.MaxInt)
468		}
469		s.nextResultSeq++
470		e.Result = result
471		e.ResultSeq = s.nextResultSeq
472		s.dirty = true
473		return e, true, nil
474	}
475	
476	// ---------- 免修 ----------
477	
478	// ApplyWaiver 提交免修申请，依据必须含实际文字。
479	//
480	// 首次提交且内容合法：状态为有效（approved），action=created。
481	// 目标要求不存在（含要求属于其他学生）、依据不含实际文字、或该要求已有
482	// 有效免修：申请被拒绝，但申请内容与具体原因保留在该学生的免修历史中，
483	// 返回的申请状态为 rejected（仍属于新建记录，action=created）。
484	// 同一编号已存在：内容（要求、依据）完全相同时返回原申请及其结果
485	// （已拒绝/已撤销的申请不会因重试重新生效）；内容不同则拒绝且不改动原申请。
486	//
487	// 学生编号、要求编号与免修编号按用户给出的完整文字参与匹配，前后空白
488	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
489	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
490	// 要求、“w1” 与 “ w1 ” 两份申请，提交必须命中编号完全一致的那一项，
491	// 申请也必须登记在完整编号的申请人名下。完整编号找不到学生时直接按业务
492	// 规则报错，不在任何学生名下新增历史；学生存在但名下没有该完整要求编号
493	// 时，即使去掉空白能碰上另一项要求，也绝不借用那份记录，而是按原规则在
494	// 申请人名下保存原要求编号、免修编号、依据原文与拒绝原因。编号为空字符串
495	// 时直接拒绝，不创建申请。依据含实际文字时其中的空白（包括前后空白）
496	// 原样保留；是否“没有依据”只按空白内容判定（见 blankBasis），绝不修剪
497	// 或改写依据原文。
498	func (s *Store) ApplyWaiver(studentID, reqID, waiverID, basis string) (w *Waiver, action Action, err error) {
499		if studentID == "" || reqID == "" || waiverID == "" {
500			return nil, "", errors.New("学生编号、要求编号和免修编号不能为空")
501		}
502		if _, ok := s.studentByID[studentID]; !ok {
503			return nil, "", fmt.Errorf("学生 %s 不存在，不能申请免修", studentID)
504		}
505		if existing := s.waiverByKey[reqKey(studentID, waiverID)]; existing != nil {
506			if existing.ReqID != reqID || existing.Basis != basis {
507				return nil, "", fmt.Errorf(
508					"学生 %s 的免修编号 %s 已存在（要求 %s、依据 %q），提交内容不同，拒绝修改",
509					studentID, waiverID, existing.ReqID, existing.Basis)
510			}
511			return existing, ActionExisted, nil
512		}
513	
514		w = &Waiver{ID: waiverID, StudentID: studentID, ReqID: reqID, Basis: basis}
515		switch {
516		case s.reqByKey[reqKey(studentID, reqID)] == nil:
517			w.Status = WaiverRejected
518			w.Reason = fmt.Sprintf("目标要求 %s 不存在或不属于该学生", reqID)
519		case blankBasis(basis):
520			w.Status = WaiverRejected
521			w.Reason = "免修依据为空"
522		default:
523			if other := s.validWaiver(studentID, reqID); other != nil {
524				w.Status = WaiverRejected
525				w.Reason = fmt.Sprintf("该要求已有有效免修 %s", other.ID)
526				break
527			}
528			w.Status = WaiverApproved
529		}
530		s.waivers = append(s.waivers, w)
531		s.waiverByKey[reqKey(studentID, waiverID)] = w
532		s.dirty = true
533		return w, ActionCreated, nil
534	}
535	
536	// validWaiver 返回某要求当前有效的免修。
537	func (s *Store) validWaiver(studentID, reqID string) *Waiver {
538		for _, w := range s.waivers {
539			if w.StudentID == studentID && w.ReqID == reqID && w.Status == WaiverApproved {
540				return w
541			}
542		}
543		return nil
544	}
545	
546	// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
547	// 重复撤销已撤销的免修：原样返回、changed=false，不改变结果。
548	// 撤销不存在的编号或撤销已被拒绝的申请：明确拒绝。
549	//
550	// 学生编号与免修编号按用户给出的完整文字参与匹配，前后空白（普通空格、
551	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
552	// “s1”与“ s1 ”两名学生、同一学生名下“w1”与“ w1 ”两份免修，撤销
553	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
554	// 学生存在但名下没有该完整免修编号时报告该免修不存在——即使去掉空白后
555	// 能碰上另一名学生或另一份免修，也绝不借用那份记录，更不能改写原编号、
556	// 合并申请或新增免修历史。撤销提示与免修历史一律使用实际命中的原编号。
557	func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, changed bool, err error) {
558		reason = strings.TrimSpace(reason)
559		if _, ok := s.studentByID[studentID]; !ok {
560			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
561		}
562		w = s.waiverByKey[reqKey(studentID, waiverID)]
563		if w == nil {
564			return nil, false, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
565		}
566		switch w.Status {
567		case WaiverApproved:
568			w.Status = WaiverRevoked
569			if reason == "" {
570				reason = "手动撤销"
571			}
572			w.Reason = reason
573			s.dirty = true
574			return w, true, nil
575		case WaiverRevoked:
576			return w, false, nil
577		default:
578			return nil, false, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
579		}
580	}
581

