}

type diskCourse struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Credit int    `json:"credit"`
	Open   bool   `json:"open"`
}
type diskStudent struct {
	ID string `json:"id"`
}
type diskReq struct {
	ID      string `json:"id"`
	Student string `json:"student"`
	Course  string `json:"course"`
}
type diskEnr struct {
	ID        string `json:"id"`
	Student   string `json:"student"`
	Req       string `json:"req"`
