// 只含空白的要求编号同样拒绝；记录文件逐字节保持原样。
func TestCLIReqWhitespaceIDRejected(t *testing.T) {
	d := &diskRecord{
		Version: 1,
		Courses: []diskCourse{
			{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
		},
		Students: []diskStudent{
			{ID: "s1"},
