		{"要求空字符串", []string{"req", "s1", "", "c1"}, []string{"不能为空"}},
		{"课程空字符串", []string{"req", "s1", "r1", ""}, []string{"不能为空"}},
		// 只含空白的要求编号不得建立。
		{"要求编号全空格", []string{"req", "s1", "  ", "c1"}, []string{"要求编号"}},
		{"要求编号全角空格", []string{"req", "s1", "　", "c1"}, []string{"要求编号"}},
