	out, _, _ = runCLI(t, file, "show", "s1")
	if !strings.Contains(out, "要求 r1 -> 课程 c1《高等数学》4 学分") ||
		strings.Contains(out, " r1 ") || strings.Contains(out, "大学物理") {
